import{z as o,x as i,o as A,c as m,q as l,j as r,D as e,d as B,s,S as n,b as a}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"边缘端的投机","description":"","frontmatter":{"title":"边缘端的投机","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/spec-edge.md","filePath":"llm/spec-edge.md","lastUpdated":1791063341000}'),d={name:"llm/spec-edge.md"};function p(D,E,C,h,c,g){const t=i("Mermaid");return A(),m("div",null,[E[2]||(E[2]=l('<h1 id="边缘端的投机" tabindex="-1">边缘端的投机 <a class="header-anchor" href="#边缘端的投机" aria-label="Permalink to &quot;边缘端的投机&quot;">​</a></h1><div class="epigraph"><p>服务器上投机在捡空闲算力，边缘上没有空闲算力可捡——能捡的只剩内存带宽和电池。</p><footer>—— 据 Leviathan et al., 2023 的成本比框架对端侧资源的重算整理</footer></div><p><a href="/llm/spec-batching-interaction">上一课</a>把批量这根轴走完：服务端批量填满算力后投机退场。边缘端是这条逻辑的极值——batch=1 是常态而非低载工况，而且连「稍胖的前向」都不便宜。本端的<a href="/llm/on-device-speculative">端侧投机解码</a>写过设备–云分工：草稿在端、校验在云。本课写另一条路：投机整个发生在端上，目标、草稿、校验都不出设备。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>端侧的资源约束把服务器的两笔账重写。第一笔是成本比 \\(c_q/c_p\\)：服务器上目标模型卡在带宽墙、算力大量闲置，校验前向近乎免费，草稿只要「更快」就赚；端上目标本身就是几 B 参数的小模型，草稿要么更小、要么零权重，两者挤同一条内存带宽，\\(c_q\\) 的相对占比高得多。第二笔是容量：手机与笔记本上，权重量化后目标已占几个 GB，一份独立草稿模型的常驻内存可能直接出局；KV 峰值还要为草稿位置多留 \\((1+\\gamma)\\) 的余量，而端侧 KV 预算本就贴着上限编。第三笔是能耗：每个被接受 token 的焦耳数才是端上的「延迟」，草稿前向的白算直接烧电池。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>按「草稿多便宜」排一条端侧谱系。<strong>零权重草稿</strong>：n-gram / 提示内复制——编辑、改写、抄写型任务里，输出大量重复提示或自身已生成的文本，复制式草稿接受率极高且不占内存、不花前向，是端侧的第一选择（检索式候选见 <a href="/llm/rest-spec">REST</a>）。<strong>自投机头</strong>：在量化目标上挂一个多 token 头或单层草稿，权重代价几十 MB 量级，词表按构造对齐，这是<a href="/llm/spec-self-draft-medusa">自投机与多 token 头</a>与<a href="/llm/spec-eagle-family">特征级草稿</a>在端上的落点；特征挂钩要求目标导出中间层，端侧推理栈要支持。<strong>同族小模型</strong>：最后才考虑，内存与热身成本都要立项。<strong>校验的形状</strong>：端侧加速器多按静态 shape 编译，\\(\\gamma\\) 可变会触发重编译；把 \\(\\gamma+1\\) 个位置补齐成固定形状、短请求掩码早退，比动态 shape 便宜。</p><p><span class="marginnote">术语翻译：「静态 shape 编译」是加速器在编译期把张量尺寸钉死来换执行效率；\\(\\gamma\\) 一变、尺寸就变，整套核要重新编译（毫秒到秒级）。所以端侧宁可把 \\(\\gamma+1\\) 个位置统一补齐成固定形状，没草稿的位置用掩码跳过——「补座位」比「每次重排桌」便宜。</span></p>',8)),(A(),r(n,null,{default:e(()=>[s(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20TASK%5B%22%E8%AF%B7%E6%B1%82%E5%88%B0%E8%BE%BE%22%5D%20--%3E%20COPY%7B%22%E5%A4%8D%E5%88%B6%E5%9E%8B%E4%BB%BB%E5%8A%A1%3F%22%7D%0A%20%20COPY%20--%3E%7C%22%E6%98%AF%22%7C%20NG%5B%22n-gram%20%2F%20%E6%8F%90%E7%A4%BA%E5%86%85%E8%8D%89%E7%A8%BF%22%5D%0A%20%20COPY%20--%3E%7C%22%E5%90%A6%22%7C%20HEAD%7B%22%E5%B8%A6%E8%87%AA%E6%8A%95%E6%9C%BA%E5%A4%B4%3F%22%7D%0A%20%20HEAD%20--%3E%7C%22%E6%98%AF%22%7C%20SH%5B%22%E5%8D%95%E5%B1%82%E8%8D%89%E7%A8%BF%20%2F%20%E5%A4%9A%20token%20%E5%A4%B4%22%5D%0A%20%20HEAD%20--%3E%7C%22%E5%90%A6%22%7C%20OFF%5B%22%E8%87%AA%E5%9B%9E%E5%BD%92%EF%BC%8C%E4%B8%8D%E5%BC%80%E6%8A%95%E6%9C%BA%22%5D%0A%20%20NG%20--%3E%20V%5B%22%CE%B3%2B1%20%E5%9B%BA%E5%AE%9A%E5%BD%A2%E7%8A%B6%E6%A0%A1%E9%AA%8C%22%5D%0A%20%20SH%20--%3E%20V%0A%20%20V%20--%3E%20ACC%5B%22%E6%8C%89%E6%8E%A5%E5%8F%97%E9%95%BF%E5%BA%A6%E6%8F%90%E4%BA%A4%22%5D%0A%20%20ACC%20--%3E%20E%5B%22%E8%83%BD%E8%80%97%E4%B8%8E%E5%BB%B6%E8%BF%9F%E8%AE%B0%E8%B4%A6%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[B("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,"端上投机的机制核心仍是那条不变式：加速 = 接受长度 ÷ 一轮成本比，变的只是成本怎么算。服务器的带宽墙让「一轮成本」近似等于一次目标步；端上「一轮成本」= 草稿前向的带宽与能耗 + 校验的增量。零权重草稿把第一项压到近零，于是即便目标只有 3–8B，接受长度 2–3 也直接兑现为约一半的步数——这解释了为什么复制式草稿在端侧的地位远高于服务器：服务器的草稿预算买得起学习型模型，端侧最稀缺的恰是那份预算。能耗账同理：每接受一个 token 摊到的权重读取次数从 \\(\\tau\\) 次目标前向降到约 \\(1+\\tau/(\\gamma+1)\\) 次，电池省的是这一截；但草稿若要独立模型常驻，内存驻留本身的功耗与换页就把账吃回去。",-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"量级感受：8B 目标 4-bit 权重约 4–5 GB，同族 0.5–1B 草稿还要再加约 0.3–0.7 GB 与一份 KV——在 8–12 GB 可用内存的手机上，这份常驻就是「出局」二字的含义；单层自投机头几十 MB，才挤得进来。")],-1)),E[6]||(E[6]=a("p",null,[a("span",{class:"marginnote"},"数字实例：\\(\\gamma=3\\)、平均每轮接受 \\(\\tau=3\\) 个 token 时，每接受一个 token 摊到的目标前向从 3 次降到约 \\(1+3/4=1.75\\) 次，权重读取省约四成——电池省的就是这一截。但若为这份 \\(\\tau=3\\) 常驻一个独立草稿模型，驻留功耗与换页会把省下的吃回去。")],-1)),(A(),r(n,null,{default:e(()=>[s(t,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E5%90%8C%E6%98%AF%E5%AD%A6%E4%B9%A0%E5%9E%8B%E8%8D%89%E7%A8%BF%2C%20%E4%B8%BA%E4%BD%95%E4%B8%A4%E7%AB%AF%E7%BB%93%E8%AE%BA%E7%9B%B8%E5%8F%8D%3F%22%5D%20--%3E%20S%5B%22%E6%9C%8D%E5%8A%A1%E5%99%A8%3A%20%E7%9B%AE%E6%A0%87%E5%A4%A7%2C%20%E5%8D%A1%E5%B8%A6%E5%AE%BD%E5%A2%99%22%5D%0A%20%20Q%20--%3E%20E%5B%22%E7%AB%AF%E4%BE%A7%3A%20%E7%9B%AE%E6%A0%87%E4%BB%85%203-8B%2C%20%E6%97%A0%E7%A9%BA%E9%97%B2%E7%AE%97%E5%8A%9B%22%5D%0A%20%20S%20--%3E%20S1%5B%22%E6%A0%A1%E9%AA%8C%E5%8A%A0%E5%AE%BD%E8%BF%91%E5%85%8D%E8%B4%B9%2C%20%E8%8D%89%E7%A8%BF%E8%B4%B5%E4%B8%80%E7%82%B9%E4%B9%9F%E8%B5%9A%22%5D%0A%20%20E%20--%3E%20E1%5B%22%E8%8D%89%E7%A8%BF%E4%B8%8E%E7%9B%AE%E6%A0%87%E6%8C%A4%E5%90%8C%E4%B8%80%E6%9D%A1%E5%86%85%E5%AD%98%E5%B8%A6%E5%AE%BD%22%5D%0A%20%20E1%20--%3E%20E2%5B%22%E8%8D%89%E7%A8%BF%E5%89%8D%E5%90%91%E7%99%BD%E7%AE%97%E7%9B%B4%E6%8E%A5%E7%83%A7%E7%94%B5%E6%B1%A0%22%5D%0A%20%20E2%20--%3E%20E3%5B%22%E7%BB%93%E8%AE%BA%3A%20%E9%9B%B6%E6%9D%83%E9%87%8D%E8%8D%89%E7%A8%BF%E4%BC%98%E5%85%88%2C%20%E5%AD%A6%E4%B9%A0%E5%9E%8B%E6%AE%BF%E5%90%8E%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=l('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>热节流让 \\(c_q/c_p\\) 随时间漂：连续生成几分钟后峰值频率下降，离线测的成本比在真机上会失真，账要按稳态温度重算。接受率也漂：端上流量高度个人化，桶统计的样本比服务端更稀，上一课的在线选择在端上退化为「任务识别 + 两三档预设」。无损声明不变，但端上常配贪心或低温采样，「无损」与「逐 token 相同」的区分更要写清。设备–云分工与纯端投机不是二选一：敏感前缀留在端上投机，长重算段走<a href="/llm/on-device-speculative">端侧投机解码</a>的云校验，按隐私与资费切分。</p><p><span class="marginnote">直觉类比：手机连跑几分钟大模型后变卡，不是错觉——芯片过热会主动降频自保。实验室里机器冰凉时测出的成本比，拿到发烫的真机上会偏乐观，所以端侧的加速比要按「跑热之后」的稳态频率重新算一遍。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>端侧 batch=1 是常态且无空闲算力：成本比、内存容量、能耗三笔账一起重写投机立项。</li><li>谱系按草稿便宜程度排：n-gram 复制零权重居首，自投机头次之，独立小模型最后。</li><li>零权重草稿在端侧价值最高：服务器买得起学习型草稿，端侧最缺的正是这份预算。</li><li>校验按固定 \\(\\gamma+1\\) 形状补齐，掩码早退，避免加速器动态 shape 重编译。</li><li>能耗省在「每接受 token 的目标前向次数」；热节流与个人化流量要求按稳态重测成本比。</li><li>出处：Leviathan et al., ICML 2023；Cai et al., <em>Medusa</em>, ICML 2024；据本仓库端侧与投机课序整理。</li></ul>',5))])}const F=o(d,[["render",p]]);export{f as __pageData,F as default};
